// SPDX-License-Identifier: MIT OR Apache-2.0
pragma solidity >=0.8.0;

// ============ Internal Imports ============
import {AbstractRoutingIsm} from "./AbstractRoutingIsm.sol";
import {IInterchainSecurityModule} from "../../interfaces/IInterchainSecurityModule.sol";
import {IMailbox} from "../../interfaces/IMailbox.sol";
import {PackageVersioned} from "../../PackageVersioned.sol";

// ============ External Imports ============
import {Address} from "@openzeppelin/contracts/utils/Address.sol";

/**
 * @title DefaultIsm
 * @notice Ownerless routing ISM that always defers to the mailbox's default ISM.
 */
contract DefaultIsm is AbstractRoutingIsm, PackageVersioned {
    IMailbox public immutable mailbox;

    constructor(address _mailbox) {
        require(Address.isContract(_mailbox), "DefaultIsm: invalid mailbox");
        mailbox = IMailbox(_mailbox);
    }

    function route(
        bytes calldata
    ) public view override returns (IInterchainSecurityModule) {
        return mailbox.defaultIsm();
    }
}

contracts/isms/routing/DomainRoutingIsm..content:
// SPDX-License-Identifier: MIT OR Apache-2.0
pragma solidity >=0.8.0;

// ============ External Imports ============
import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";

// ============ Internal Imports ============
import {AbstractRoutingIsm} from "./AbstractRoutingIsm.sol";
import {IInterchainSecurityModule} from "../../interfaces/IInterchainSecurityModule.sol";
import {Message} from "../../libs/Message.sol";
import {TypeCasts} from "../../libs/TypeCasts.sol";
import {EnumerableMapExtended} from "../../libs/EnumerableMapExtended.sol";
import {PackageVersioned} from "../../PackageVersioned.sol";

/**
 * @title DomainRoutingIsm
 */
contract DomainRoutingIsm is
    AbstractRoutingIsm,
    OwnableUpgradeable,
    PackageVersioned
{
    using EnumerableMapExtended for EnumerableMapExtended.UintToBytes32Map;
    using Message for bytes;
    using TypeCasts for bytes32;
    using TypeCasts for address;
    using Address for address;
    using Strings for uint32;

    // ============ Mutable Storage ============
    EnumerableMapExtended.UintToBytes32Map internal _modules;

    // ============ Events ============
    event ModuleSet(uint32 indexed domain, address indexed module);
    event ModuleRemoved(uint32 indexed domain);

    // ============ Structs ============
    struct IsmConfig {
        uint32 domain;
        IInterchainSecurityModule ism;
    }

    // ============ External Functions ============

    /**
     * @param _owner The owner of the contract.
     */
    function initialize(address _owner) public initializer {
        __Ownable_init();
        _transferOwnership(_owner);
    }

    /**
     * @notice Sets the ISMs to be used for the specified origin domains
     * @param _owner The owner of the contract.
     * @param _domains The origin domains
     * @param __modules The ISMs to use to verify messages
     */
    function initialize(
        address _owner,
        uint32[] calldata _domains,
        IInterchainSecurityModule[] calldata __modules
    ) public initializer {
        __Ownable_init();
        _initialize(_owner, _domains, __modules);
    }

    function _initialize(
        address _owner,
        uint32[] memory _domains,
        IInterchainSecurityModule[] memory __modules
    ) internal {
        require(_domains.length == __modules.length, "length mismatch");
        uint256 _length = _domains.length;
        for (uint256 i = 0; i < _length; ++i) {
            _set(_domains[i], address(__modules[i]));
        }
        _transferOwnership(_owner);
    }

    /**
     * @notice Sets the ISM to be used for the specified origin domain
     * @param _domain The origin domain
     * @param _module The ISM to use to verify messages
     */
    function set(
        uint32 _domain,
        IInterchainSecurityModule _module
    ) external onlyOwner {
        _set(_domain, address(_module));
    }

    /**
     * @notice Sets the ISMs to be used for the specified origin domains
     * @param _configs The origin domains and ISMs to enroll
     */
    function setIsms(IsmConfig[] calldata _configs) external onlyOwner {
        for (uint256 i = 0; i < _configs.length; ++i) {
            _set(_configs[i].domain, address(_configs[i].ism));
        }
    }

    /**
     * @notice Removes the specified origin domain
     * @param _domain The origin domain
     */
    function remove(uint32 _domain) external onlyOwner {
        _remove(_domain);
    }

    /**
     * @notice Removes the specified origin domains
     * @param _domains The origin domains to remove
     */
    function removeIsms(uint32[] calldata _domains) external onlyOwner {
        for (uint256 i = 0; i < _domains.length; ++i) {
            _remove(_domains[i]);
        }
    }

    function domains() external view returns (uint256[] memory) {
        return _modules.keys();
    }

    function module(
        uint32 origin
    ) public view virtual returns (IInterchainSecurityModule) {
        (bool contained, bytes32 _module) = _modules.tryGet(origin);
        if (contained) {
            return IInterchainSecurityModule(_module.bytes32ToAddress());
        }
        revert(_originNotFoundError(origin));
    }

    // ============ Public Functions ============
    /**
     * @notice Returns the ISM responsible for verifying _message
     * @dev Can change based on the content of _message
     * @param _message Formatted Hyperlane message (see Message.sol).
     * @return module The ISM to use to verify _message
     */
    function route(
        bytes calldata _message
    ) public view override returns (IInterchainSecurityModule) {
        return module(_message.origin());
    }

    // ============ Internal Functions ============

    /**
     * @notice Removes the specified origin domain's ISM
     * @param _domain The origin domain
     */
    function _remove(uint32 _domain) internal virtual {
        require(_modules.remove(_domain), _originNotFoundError(_domain));
        emit ModuleRemoved(_domain);
    }

    function _originNotFoundError(
        uint32 _origin
    ) internal pure returns (string memory) {
        return string.concat("No ISM found for origin: ", _origin.toString());
    }

    /**
     * @notice Sets the ISM to be used for the specified origin domain
     * @param _domain The origin domain
     * @param _module The ISM to use to verify messages
     */
    function _set(uint32 _domain, address _module) internal virtual {
        require(_module.isContract(), "ISM must be a contract");
        _modules.set(_domain, _module.addressToBytes32());
        emit ModuleSet(_domain, _module);
    }
}

contracts/isms/routing/DomainRoutingIsmF.content:
// SPDX-License-Identifier: MIT OR Apache-2.0
pragma solidity >=0.8.0;

// ============ Internal Imports ============
import {DomainRoutingIsm} from "./DomainRoutingIsm.sol";
import {IInterchainSecurityModule} from "../../interfaces/IInterchainSecurityModule.sol";
import {MinimalProxy} from "../../libs/MinimalProxy.sol";
import {PackageVersioned} from "../../PackageVersioned.sol";

abstract contract AbstractDomainRoutingIsmFactory is PackageVersioned {
    /**
     * @notice Emitted when a routing module is deployed
     * @param module The deployed ISM
     */
    event ModuleDeployed(DomainRoutingIsm module);

    // ============ External Functions ============

    /**
     * @notice Deploys and initializes a DomainRoutingIsm using a minimal proxy
     * @param _owner The owner to set on the ISM
     * @param _domains The origin domains
     * @param _modules The ISMs to use to verify messages
     */
    function deploy(
        address _owner,
        uint32[] calldata _domains,
        IInterchainSecurityModule[] calldata _modules
    ) external returns (DomainRoutingIsm) {
        DomainRoutingIsm _ism = DomainRoutingIsm(
            MinimalProxy.create(implementation())
        );
        emit ModuleDeployed(_ism);
        _ism.initialize(_owner, _domains, _modules);
        return _ism;
    }

    function implementation() public view virtual returns (address);
}

/**
 * @title DomainRoutingIsmFactory
 */
contract DomainRoutingIsmFactory is AbstractDomainRoutingIsmFactory {
    // ============ Immutables ============
    address internal immutable _implementation;

    constructor() {
        _implementation = address(new DomainRoutingIsm());
    }

    function implementation() public view override returns (address) {
        return _implementation;
    }
}

contracts/isms/routing/IncrementalDomain.content:
// SPDX-License-Identifier: MIT OR Apache-2.0
pragma solidity >=0.8.0;

// ============ Internal Imports ============
import {DomainRoutingIsm} from "./DomainRoutingIsm.sol";
import {EnumerableMapExtended} from "../../libs/EnumerableMapExtended.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title IncrementalDomainRoutingIsm
 * @notice A DomainRoutingIsm variant that enforces append-only domain configurations
 * @dev Reverts when attempting to set a domain that already exists or remove any domain.
 */
contract IncrementalDomainRoutingIsm is DomainRoutingIsm {
    using EnumerableMapExtended for EnumerableMapExtended.UintToBytes32Map;
    using Strings for uint32;

    /**
     * @inheritdoc DomainRoutingIsm
     * @dev Reverts if the domain already exists in the routing table
     */
    function _set(uint32 _domain, address _module) internal override {
        require(
            !_modules.contains(_domain),
            string.concat(
                "IncrementalDomainRoutingIsm: Domain already exists: ",
                _domain.toString()
            )
        );
        super._set(_domain, _module);
    }

    /**
     * @inheritdoc DomainRoutingIsm
     * @dev Always reverts - IncrementalDomainRoutingIsm does not support removal
     */
    function _remove(uint32 /*_domain*/) internal override {
        revert("IncrementalDomainRoutingIsm: removal not supported");
    }
}

// SPDX-License-Identifier: MIT OR Apache-2.0
pragma solidity >=0.8.0;

// ============ Internal Imports ============
import {IncrementalDomainRoutingIsm} from "./IncrementalDomainRoutingIsm.sol";
import {DomainRoutingIsm} from "./DomainRoutingIsm.sol";
import {AbstractDomainRoutingIsmFactory} from "./DomainRoutingIsmFactory.sol";

/**
 * @title IncrementalDomainRoutingIsmFactory
 * @notice Factory for deploying IncrementalDomainRoutingIsm contracts as minimal proxies
 */
contract IncrementalDomainRoutingIsmFactory is AbstractDomainRoutingIsmFactory {
    // ============ Immutables ============
    address internal immutable _implementation;

    constructor() {
        _implementation = address(new IncrementalDomainRoutingIsm());
    }

    function implementation() public view override returns (address) {
        return _implementation;
    }
}

contracts/isms/routing/TimelockRouter.so.content:
// SPDX-License-Identifier: MIT OR Apache-2.0
pragma solidity >=0.8.0;

/*@@@@@@@       @@@@@@@@@
 @@@@@@@@@       @@@@@@@@@
  @@@@@@@@@       @@@@@@@@@
   @@@@@@@@@       @@@@@@@@@
    @@@@@@@@@@@@@@@@@@@@@@@@@
     @@@@@  HYPERLANE  @@@@@@@
    @@@@@@@@@@@@@@@@@@@@@@@@@
   @@@@@@@@@       @@@@@@@@@
  @@@@@@@@@       @@@@@@@@@
 @@@@@@@@@       @@@@@@@@@
@@@@@@@@@       @@@@@@@@*/

// ============ Internal Imports ============
import {Router} from "../../client/Router.sol";
import {IPostDispatchHook} from "../../interfaces/hooks/IPostDispatchHook.sol";
import {IRoutingHook} from "../../interfaces/hooks/IRoutingHook.sol";
import {IInterchainSecurityModule} from "../../interfaces/IInterchainSecurityModule.sol";
import {Message} from "../../libs/Message.sol";

/**
 * @title TimelockRouter
 * @notice Combined hook and ISM for time-delayed message verification.
 * @dev This contract serves three roles:
 * 1. Hook: On origin chain, sends message IDs to destination routers
 * 2. Router: On destination chain, receives message IDs and stores readyAt time
 * 3. ISM: On destination chain, verifies messages after the timelock window
 *
 * @dev **Subclass contract**: `postDispatch`, `quoteDispatch`, and `verify`
 * enforce this contract's invariants (notably `_isLatestDispatched(id)`).
 * Subclasses customize via the internal hooks:
 * - `_encodePayload` — cross-chain payload, shared by `postDispatch` and
 *   `quoteDispatch` so the quote tracks the dispatched payload
 * - `_TimelockRouter_onDispatch` — origin-side side effects (sender binding,
 *   replay guards, etc.)
 * - `_handle` — compute a per-message wait and call `_TimelockRouter_commitReadyAt`
 * - `_TimelockRouter_verify` — extend destination-side verification
 * See `DelayedFlowRouterHookIsm` for an amount-sensitive extension.
 */
contract TimelockRouter is
    Router,
    IRoutingHook,
    IPostDispatchHook,
    IInterchainSecurityModule
{
    using Message for bytes;

    // ============ Events ============
    event MessageQueued(bytes32 indexed messageId, uint48 readyAt);

    // ============ Errors ============
    error MessageNotReadyUntil(uint48 readyAt);

    // ============ Immutables ============
    uint48 public immutable timelockWindow;

    // ============ Storage ============
    /// @dev Mapping of message ID => timestamp when message is ready for verification
    mapping(bytes32 messageId => uint48 timestamp) public readyAt;

    // ============ Constructor ============
    constructor(address _mailbox, uint48 _timelockWindow) Router(_mailbox) {
        timelockWindow = _timelockWindow;
    }

    // ============ IPostDispatchHook Implementation ============

    /// @inheritdoc IPostDispatchHook
    function hookType() external pure virtual returns (uint8) {
        return uint8(IPostDispatchHook.HookTypes.ROUTING);
    }

    /// @inheritdoc IRoutingHook
    function hooks(
        uint32 /*destination*/
    ) external view returns (IPostDispatchHook) {
        // always routes to the configured hook
        return hook;
    }

    /// @inheritdoc IPostDispatchHook
    function supportsMetadata(
        bytes calldata /*metadata*/
    ) external pure returns (bool) {
        return true;
    }

    /**
     * @inheritdoc IPostDispatchHook
     * @dev Enforces `_isLatestDispatched(id)` — so only a message currently
     * being dispatched through the Mailbox reaches the cross-chain send —
     * then runs subclass side effects via `_TimelockRouter_onDispatch` and
     * forwards `_encodePayload(message)`.
     */
    function postDispatch(
        bytes calldata /*metadata*/,
        bytes calldata message
    ) external payable {
        require(_isLatestDispatched(message.id()), "message not dispatching");
        _TimelockRouter_onDispatch(message);
        _Router_dispatch(
            message.destination(),
            msg.value,
            _encodePayload(message)
        );
    }

    /// @dev Origin-side side-effect hook, invoked by `postDispatch` after it
    /// enforces `_isLatestDispatched`. Default is a no-op; subclasses override
    /// to add sender binding, replay guards, bucket credits, etc.
    function _TimelockRouter_onDispatch(
        bytes calldata /*message*/
    ) internal virtual {}

    /// @dev The cross-chain payload. Shared by `postDispatch` and
    /// `quoteDispatch` so the quote can never drift from the dispatched
    /// payload. Default carries just the message id; subclasses override to
    /// carry additional data the destination needs.
    function _encodePayload(
        bytes calldata message
    ) internal view virtual returns (bytes memory) {
        return abi.encode(message.id());
    }

    /// @inheritdoc IPostDispatchHook
    function quoteDispatch(
        bytes calldata /*metadata*/,
        bytes calldata message
    ) external view returns (uint256) {
        return
            _Router_quoteDispatch(
                message.destination(),
                _encodePayload(message)
            );
    }

    // ============ Router Implementation ============

    /// @inheritdoc Router
    /// @dev Default preverification: decode the id and commit `readyAt` at
    /// the constant `timelockWindow`. Subclasses override this entirely to
    /// derive an amount-sensitive wait, then call
    /// `_TimelockRouter_commitReadyAt` to persist the result.
    function _handle(
        uint32 /*_origin*/,
        bytes32 /*_sender*/,
        bytes calldata payload
    ) internal virtual override {
        bytes32 id = abi.decode(payload, (bytes32));
        _TimelockRouter_commitReadyAt(id, timelockWindow);
    }

    /// @dev Leaf helper for `_handle` overrides: one-shot replay guard and
    /// `readyAt` write. `wait` is the number of seconds the message must be
    /// withheld from the ISM before `verify` will pass.
    function _TimelockRouter_commitReadyAt(bytes32 id, uint48 wait) internal {
        require(
            readyAt[id] == 0,
            "TimelockRouter: message already preverified"
        );
        uint48 messageReadyAt = uint48(block.timestamp) + wait;
        readyAt[id] = messageReadyAt;
        emit MessageQueued(id, messageReadyAt);
    }

    // ============ IInterchainSecurityModule Implementation ============

    /// @inheritdoc IInterchainSecurityModule
    function moduleType() external pure virtual returns (uint8) {
        return uint8(IInterchainSecurityModule.Types.NULL);
    }

    /// @inheritdoc IInterchainSecurityModule
    /// @dev Subclasses extend verification via the `_TimelockRouter_verify` hook.
    function verify(
        bytes calldata /*metadata*/,
        bytes calldata message
    ) external view returns (bool) {
        return _TimelockRouter_verify(message);
    }

    /// @dev Core `verify` logic. Subclasses extend by overriding this hook
    /// (adding their own checks and delegating to `super`).
    function _TimelockRouter_verify(
        bytes calldata message
    ) internal view virtual returns (bool) {
        bytes32 id = message.id();
        uint48 messageReadyAt = readyAt[id];

        require(messageReadyAt > 0, "TimelockRouter: message not preverified");

        if (messageReadyAt > block.timestamp) {
            revert MessageNotReadyUntil(messageReadyAt);
        }

        return true;
    }
}

