// SPDX-License-Identifier: MIT OR Apache-2.0
pragma solidity >=0.6.11;

// Library for building bytecode of minimal proxies (see https://eips.ethereum.org/EIPS/eip-1167)
library MinimalProxy {
    bytes20 private constant PREFIX =
        hex"3d602d80600a3d3981f3363d3d373d3d3d363d73";
    bytes15 private constant SUFFIX = hex"5af43d82803e903d91602b57fd5bf3";

    function create(address implementation) internal returns (address proxy) {
        bytes memory _bytecode = bytecode(implementation);
        assembly {
            proxy := create(0, add(_bytecode, 32), mload(_bytecode))
        }
    }

    function bytecode(
        address implementation
    ) internal pure returns (bytes memory) {
        return abi.encodePacked(PREFIX, bytes20(implementation), SUFFIX);
    }
}

contracts/libs/OPL2ToL1Metadata.sol.content:
// SPDX-License-Identifier: MIT OR Apache-2.0
pragma solidity >=0.8.0;

/**
 * @title Hyperlane OPL2ToL1Metadata Library
 * @notice Library for formatted metadata used by OPL2ToL1Ism
 */
library OPL2ToL1Metadata {
    // bottom offset to the start of message id in the metadata
    uint256 private constant MESSAGE_ID_OFFSET = 120;
    // from IOptimismPortal.WithdrawalTransaction
    // Σ {
    //      nonce                          = 32 bytes
    //      PADDING + sender               = 32 bytes
    //      PADDING + target               = 32 bytes
    //      value                          = 32 bytes
    //      gasLimit                       = 32 bytes
    //      _data
    //          OFFSET                      = 32 bytes
    //          LENGTH                      = 32 bytes
    // } = 252 bytes
    uint256 private constant FIXED_METADATA_LENGTH = 252;
    // metadata here is double encoded call relayMessage(..., preVerifyMessage)
    // Σ {
    //      _selector                       =  4 bytes
    //      _nonce                          = 32 bytes
    //      PADDING + _sender               = 32 bytes
    //      PADDING + _target               = 32 bytes
    //      _value                          = 32 bytes
    //      _minGasLimit                    = 32 bytes
    //      _data
    //          OFFSET                      = 32 bytes
    //          LENGTH                      = 32 bytes
    //          PADDING + preVerifyMessage   = 96 bytes
    // } = 324 bytes
    uint256 private constant MESSENGER_CALLDATA_LENGTH = 324;

    /**
     * @notice Returns the message ID.
     * @param _metadata OptimismPortal.WithdrawalTransaction encoded calldata
     * @return ID of `_metadata`
     */
    function messageId(
        bytes calldata _metadata
    ) internal pure returns (bytes32) {
        uint256 metadataLength = _metadata.length;
        return
            bytes32(
                _metadata[metadataLength - MESSAGE_ID_OFFSET:metadataLength -
                    MESSAGE_ID_OFFSET +
                    32]
            );
    }

    function checkCalldataLength(
        bytes calldata _metadata
    ) internal pure returns (bool) {
        return
            _metadata.length ==
            MESSENGER_CALLDATA_LENGTH + FIXED_METADATA_LENGTH;
    }
}

contracts/libs/OPL2ToL1Withdrawal.sol.content:
// SPDX-License-Identifier: MIT OR Apache-2.0
pragma solidity >=0.8.0;

import {IOptimismPortal} from "../interfaces/optimism/IOptimismPortal.sol";

/**
 * @title Hyperlane OPL2ToL1Withdrawal Library
 * @notice Library to calculate the withdrawal hash for OPL2ToL1CcipReadIsm
 * validation
 */
library OPL2ToL1Withdrawal {
    /// @dev Copied from Hashing.sol of Optimism
    function hashWithdrawal(
        IOptimismPortal.WithdrawalTransaction memory _tx
    ) internal pure returns (bytes32) {
        return
            keccak256(
                abi.encode(
                    _tx.nonce,
                    _tx.sender,
                    _tx.target,
                    _tx.value,
                    _tx.gasLimit,
                    _tx.data
                )
            );
    }

    function encodeData(
        bytes32 _proveMessageId,
        bytes32 _finalizeMessageId
    ) internal pure returns (bytes memory) {
        return abi.encode(_proveMessageId, _finalizeMessageId);
    }

    function proveMessageId(
        IOptimismPortal.WithdrawalTransaction memory _tx
    ) internal pure returns (bytes32) {
        (bytes32 _proveMessageId, ) = abi.decode(_tx.data, (bytes32, bytes32));
        return _proveMessageId;
    }

    function finalizeMessageId(
        IOptimismPortal.WithdrawalTransaction memory _tx
    ) internal pure returns (bytes32) {
        (, bytes32 _finalizeMessageId) = abi.decode(
            _tx.data,
            (bytes32, bytes32)
        );
        return _finalizeMessageId;
    }
}

