// SPDX-License-Identifier: MIT OR Apache-2.0
pragma solidity >=0.8.0;

import {ITokenBridge, Quote} from "../../interfaces/ITokenBridge.sol";
import {PackageVersioned} from "../../PackageVersioned.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {EnumerableDomainSet} from "../../libs/EnumerableDomainSet.sol";

struct DestinationConfig {
    address depositAddress;
    uint256 feeBps;
}

/**
 * @title TokenBridgeDepositAddress
 * @notice Generic ITokenBridge adapter for deposit-address-based bridges.
 * @dev Bridges by transferring tokens to a configured deposit address on the origin chain.
 *      Settlement to the destination recipient happens offchain via the external issuer.
 *      Assumes standard ERC20 transfer semantics; native-token deposit lanes, fee-on-transfer,
 *      rebasing, and ERC-777-style callback tokens are unsupported.
 */
contract TokenBridgeDepositAddress is
    ITokenBridge,
    Ownable,
    PackageVersioned,
    EnumerableDomainSet
{
    using SafeERC20 for IERC20;
    using EnumerableSet for EnumerableSet.Bytes32Set;

    uint256 internal constant BPS_DENOMINATOR = 10_000;

    error InvalidToken(address token);
    error NativeFeeNotSupported(uint256 value);
    error DestinationNotConfigured(uint32 destination);
    error RecipientNotConfigured(uint32 destination, bytes32 recipient);
    error InvalidDepositAddress(uint32 destination, bytes32 recipient);
    error InvalidFeeBps(uint256 feeBps);

    event DestinationConfigured(
        uint32 indexed destination,
        address indexed depositAddress,
        bytes32 indexed recipient,
        uint256 feeBps
    );
    event DestinationRemoved(
        uint32 indexed destination,
        bytes32 indexed recipient
    );
    event SentTransferRemoteViaDepositAddress(
        uint32 indexed destination,
        bytes32 indexed recipient,
        address indexed depositAddress,
        uint256 amount,
        uint256 feeAmount,
        uint256 feeBps,
        uint256 nonce
    );

    IERC20 public immutable wrappedToken;

    mapping(uint32 destination => EnumerableSet.Bytes32Set recipients)
        private _configuredRecipients;
    mapping(uint32 destination => mapping(bytes32 recipient => DestinationConfig config))
        private _destinationConfigs;

    uint256 public nonce;

    constructor(address _token, address _owner) {
        if (!(_token.code.length > 0)) revert InvalidToken(_token);
        wrappedToken = IERC20(_token);
        _transferOwnership(_owner);
    }

    function token() public view returns (address) {
        return address(wrappedToken);
    }

    function quoteTransferRemote(
        uint32 _destination,
        bytes32 _recipient,
        uint256 _amount
    ) external view override returns (Quote[] memory quotes) {
        DestinationConfig memory config = _getDestinationConfig(
            _destination,
            _recipient
        );
        uint256 feeAmount = _computeFee(_amount, config.feeBps);

        quotes = new Quote[](1);
        quotes[0] = Quote({
            token: address(wrappedToken),
            amount: _amount + feeAmount
        });
    }

    function transferRemote(
        uint32 _destination,
        bytes32 _recipient,
        uint256 _amount
    ) external payable override returns (bytes32) {
        require(_amount > 0, "amount must be > 0");
        if (msg.value != 0) revert NativeFeeNotSupported(msg.value);

        DestinationConfig memory config = _getDestinationConfig(
            _destination,
            _recipient
        );
        uint256 feeAmount = _computeFee(_amount, config.feeBps);
        nonce++;

        uint256 grossAmount = _amount + feeAmount;
        wrappedToken.safeTransferFrom(
            msg.sender,
            config.depositAddress,
            grossAmount
        );

        emit SentTransferRemoteViaDepositAddress(
            _destination,
            _recipient,
            config.depositAddress,
            _amount,
            feeAmount,
            config.feeBps,
            nonce
        );

        return bytes32(0);
    }

    function addDestinationConfig(
        uint32 _destination,
        address _depositAddress,
        bytes32 _recipient,
        uint256 _feeBps
    ) external onlyOwner {
        if (_depositAddress == address(0)) {
            revert InvalidDepositAddress(_destination, _recipient);
        }
        if (_feeBps >= BPS_DENOMINATOR) {
            revert InvalidFeeBps(_feeBps);
        }
        // Prevent accidental overwrites of existing deposit address configs.
        // To update, first removeDestinationConfig then addDestinationConfig.
        require(
            _destinationConfigs[_destination][_recipient].depositAddress ==
                address(0),
            "deposit address already configured"
        );

        _addDomain(_destination);
        _configuredRecipients[_destination].add(_recipient);
        _destinationConfigs[_destination][_recipient] = DestinationConfig({
            depositAddress: _depositAddress,
            feeBps: _feeBps
        });

        emit DestinationConfigured(
            _destination,
            _depositAddress,
            _recipient,
            _feeBps
        );
    }

    function removeDestinationConfig(
        uint32 _destination,
        bytes32 _recipient
    ) external onlyOwner {
        if (!_containsDomain(_destination)) {
            revert DestinationNotConfigured(_destination);
        }
        if (!_configuredRecipients[_destination].remove(_recipient)) {
            revert RecipientNotConfigured(_destination, _recipient);
        }

        delete _destinationConfigs[_destination][_recipient];
        if (_configuredRecipients[_destination].length() == 0) {
            _removeDomain(_destination);
        }

        emit DestinationRemoved(_destination, _recipient);
    }

    function getDestinationConfig(
        uint32 _destination,
        bytes32 _recipient
    ) external view returns (DestinationConfig memory) {
        return _getDestinationConfig(_destination, _recipient);
    }

    function getDomainConfigs()
        external
        view
        returns (
            uint32[] memory domains,
            address[] memory depositAddresses,
            bytes32[] memory recipients,
            uint256[] memory feeBpsValues
        )
    {
        uint32[] memory configuredDomains = _getDomains();
        uint256 domainLen = configuredDomains.length;
        uint256 configLen;
        for (uint256 i = 0; i < domainLen; i++) {
            configLen += _configuredRecipients[configuredDomains[i]].length();
        }

        domains = new uint32[](configLen);
        depositAddresses = new address[](configLen);
        recipients = new bytes32[](configLen);
        feeBpsValues = new uint256[](configLen);

        uint256 index;
        for (uint256 i = 0; i < domainLen; i++) {
            uint32 domain = configuredDomains[i];
            uint256 recipientLen = _configuredRecipients[domain].length();
            for (uint256 j = 0; j < recipientLen; j++) {
                bytes32 recipient = _configuredRecipients[domain].at(j);
                DestinationConfig memory config = _destinationConfigs[domain][
                    recipient
                ];
                domains[index] = domain;
                depositAddresses[index] = config.depositAddress;
                recipients[index] = recipient;
                feeBpsValues[index] = config.feeBps;
                index++;
            }
        }
    }

    function _computeFee(
        uint256 _amount,
        uint256 _feeBps
    ) internal pure returns (uint256) {
        return (_amount * _feeBps) / BPS_DENOMINATOR;
    }

    function _getDestinationConfig(
        uint32 _destination,
        bytes32 _recipient
    ) internal view returns (DestinationConfig memory config) {
        if (!_containsDomain(_destination)) {
            revert DestinationNotConfigured(_destination);
        }

        if (!_configuredRecipients[_destination].contains(_recipient)) {
            revert RecipientNotConfigured(_destination, _recipient);
        }

        config = _destinationConfigs[_destination][_recipient];
        if (config.depositAddress == address(0)) {
            revert InvalidDepositAddress(_destination, _recipient);
        }
    }
}

contracts/token/CrossCollateralRouter.so.content:
// SPDX-License-Identifier: MIT OR Apache-2.0
pragma solidity >=0.8.0;

/*@@@@@@@       @@@@@@@@@
 @@@@@@@@@       @@@@@@@@@
  @@@@@@@@@       @@@@@@@@@
   @@@@@@@@@       @@@@@@@@@
    @@@@@@@@@@@@@@@@@@@@@@@@@
     @@@@@  HYPERLANE  @@@@@@@
    @@@@@@@@@@@@@@@@@@@@@@@@@
   @@@@@@@@@       @@@@@@@@@
  @@@@@@@@@       @@@@@@@@@
 @@@@@@@@@       @@@@@@@@@
@@@@@@@@@       @@@@@@@@*/

// ============ Core Imports ============
import {HypERC20Collateral} from "./HypERC20Collateral.sol";
import {TokenMessage} from "./libs/TokenMessage.sol";
import {TypeCasts} from "../libs/TypeCasts.sol";
import {IPostDispatchHook} from "../interfaces/hooks/IPostDispatchHook.sol";
import {ITokenBridge, Quote} from "../interfaces/ITokenBridge.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

// ============ Local Imports ============
import {ICrossCollateralFee} from "./interfaces/ICrossCollateralFee.sol";
import {IRebalanceTargets} from "./interfaces/IRebalanceTargets.sol";

/**
 * @title CrossCollateralRouter
 * @notice Multi-router collateral: direct 1-message atomic transfers between
 * collateral routers, both cross-chain and same-chain.
 * @dev Extends HypERC20Collateral. Each deployed instance holds collateral for
 * one ERC20. Enrolled routers are other CrossCollateralRouter instances (same or
 * different token) that this instance trusts to send/receive transfers.
 * CrossCollateralRouter assumes standard ERC20 behavior with exact transfer
 * amounts. Rebasing tokens, fee-on-transfer tokens, and ERC777 tokens are not
 * supported due to exact-amount accounting in transfer/handle flows.
 *
 * Overrides:
 *  - handle(): accepts messages from the mailbox (cross-chain) or directly
 *    from enrolled routers on the same chain.
 */
// solhint-disable-next-line hyperlane/enumerable-domain-mapping
contract CrossCollateralRouter is
    HypERC20Collateral,
    ICrossCollateralFee,
    IRebalanceTargets
{
    using TypeCasts for address;
    using TypeCasts for bytes32;
    using SafeERC20 for IERC20;
    using EnumerableSet for EnumerableSet.Bytes32Set;
    using EnumerableSet for EnumerableSet.UintSet;

    // ============ Events ============

    event CrossCollateralRouterEnrolled(
        uint32 indexed domain,
        bytes32 indexed router
    );
    event CrossCollateralRouterUnenrolled(
        uint32 indexed domain,
        bytes32 indexed router
    );
    event RebalanceTargetAdded(uint32 indexed domain, bytes32 indexed target);
    event RebalanceTargetRemoved(uint32 indexed domain, bytes32 indexed target);

    // ============ Storage ============

    /// @notice Additional enrolled routers by domain (beyond the standard
    /// enrolled remote router). Local routers use localDomain as key.
    mapping(uint32 domain => EnumerableSet.Bytes32Set routers)
        private _crossCollateralRouters;

    /// @notice Tracks which domains have at least one CrossCollateral-enrolled router,
    /// enabling on-chain enumeration for the SDK reader.
    EnumerableSet.UintSet private _crossCollateralDomains;

    /// @notice Additional allowed rebalance targets by domain, beyond the
    /// enrolled remote router. Consulted by `isRebalanceTarget`.
    // solhint-disable-next-line hyperlane/enumerable-domain-mapping
    mapping(uint32 domain => EnumerableSet.Bytes32Set targets)
        private _rebalanceTargets;

    // ============ Constructor ============

    constructor(
        address erc20,
        uint256 _scaleNumerator,
        uint256 _scaleDenominator,
        address _mailbox
    ) HypERC20Collateral(erc20, _scaleNumerator, _scaleDenominator, _mailbox) {}

    // ============ Router Management (onlyOwner) ============

    function enrollCrossCollateralRouters(
        uint32[] calldata _domains,
        bytes32[] calldata _routers
    ) external onlyOwner {
        require(_domains.length == _routers.length, "CCR: length mismatch");
        for (uint256 i = 0; i < _domains.length; i++) {
            if (_crossCollateralRouters[_domains[i]].add(_routers[i])) {
                _crossCollateralDomains.add(uint256(_domains[i]));
                emit CrossCollateralRouterEnrolled(_domains[i], _routers[i]);
            }
        }
    }

    function unenrollCrossCollateralRouters(
        uint32[] calldata _domains,
        bytes32[] calldata _routers
    ) external onlyOwner {
        require(_domains.length == _routers.length, "CCR: length mismatch");
        for (uint256 i = 0; i < _domains.length; i++) {
            if (_crossCollateralRouters[_domains[i]].remove(_routers[i])) {
                if (_crossCollateralRouters[_domains[i]].length() == 0) {
                    _crossCollateralDomains.remove(uint256(_domains[i]));
                    // Last cross-collateral route for this domain is gone; if no
                    // route remains at all, clear its rebalance config so a
                    // removed route cannot retain rebalance authority.
                    if (
                        !_MovableCollateralRouter_hasRebalanceRoutes(
                            _domains[i]
                        )
                    ) {
                        _clearRebalanceState(_domains[i]);
                    }
                }
                emit CrossCollateralRouterUnenrolled(_domains[i], _routers[i]);
            }
        }
    }

    function crossCollateralRouters(
        uint32 _domain,
        bytes32 _router
    ) external view returns (bool) {
        return _crossCollateralRouters[_domain].contains(_router);
    }

    // ============ Enumeration ============

    function getCrossCollateralRouters(
        uint32 _domain
    ) external view returns (bytes32[] memory) {
        return _crossCollateralRouters[_domain].values();
    }

    /// @notice Returns all domains that have at least one CrossCollateral-enrolled router.
    function getCrossCollateralDomains()
        external
        view
        returns (uint32[] memory domains)
    {
        uint256 len = _crossCollateralDomains.length();
        domains = new uint32[](len);
        for (uint256 i = 0; i < len; i++) {
            domains[i] = uint32(_crossCollateralDomains.at(i));
        }
    }

    // ============ Rebalance Targets (onlyOwner) ============

    /// @notice Adds an allowed rebalance target for `_domain`.
    function addRebalanceTarget(
        uint32 _domain,
        bytes32 _target
    ) external onlyOwner {
        if (_rebalanceTargets[_domain].add(_target)) {
            emit RebalanceTargetAdded(_domain, _target);
        }
    }

    /// @notice Removes a previously allowed rebalance target for `_domain`.
    function removeRebalanceTarget(
        uint32 _domain,
        bytes32 _target
    ) external onlyOwner {
        if (_rebalanceTargets[_domain].remove(_target)) {
            emit RebalanceTargetRemoved(_domain, _target);
        }
    }

    /// @notice Returns the explicitly added rebalance targets for `_domain`.
    /// @dev Excludes the enrolled remote router, which is always a valid target.
    function rebalanceTargets(
        uint32 _domain
    ) external view returns (bytes32[] memory) {
        return _rebalanceTargets[_domain].values();
    }

    /// @inheritdoc IRebalanceTargets
    /// @dev The enrolled remote router is always a valid target; additional
    /// targets are opt-in via `addRebalanceTarget`. Cross-collateral routers
    /// (enrolled via `enrollCrossCollateralRouters`) are NOT automatically valid
    /// targets and must be added explicitly with `addRebalanceTarget`. The zero
    /// address is never a valid target, even when `_domain` has no enrolled router.
    function isRebalanceTarget(
        uint32 _domain,
        bytes32 _target
    ) external view override returns (bool) {
        return
            _target != bytes32(0) &&
            (_target == routers(_domain) ||
                _rebalanceTargets[_domain].contains(_target));
    }

    // ============ Destination Gas Override ============

    /// @dev Overrides GasRouter._setDestinationGas to also accept CrossCollateral-enrolled
    /// domains (not just default Router._routers). Excludes localDomain since
    /// same-chain transfers skip mailbox dispatch.
    function _setDestinationGas(uint32 domain, uint256 gas) internal override {
        require(domain != localDomain, "CCR: no gas for local domain");
        require(
            routers(domain) != bytes32(0) ||
                _crossCollateralRouters[domain].length() > 0,
            "CCR: domain has no routers"
        );
        destinationGas[domain] = gas;
        emit GasSet(domain, gas);
    }

    // ============ Movable Collateral Overrides ============

    /// @notice Emitted when the CCR override `setRecipient` writes the
    /// per-domain rebalance recipient. Distinct from any base-contract event
    /// so off-chain consumers can attribute changes to the CCR admin path.
    event CCRRecipientSet(uint32 indexed domain, bytes32 recipient);

    /// @notice Emitted when the CCR override `addBridge` registers a new
    /// rebalance bridge for a CCR-enrolled domain.
    event CCRBridgeAdded(uint32 indexed domain, address indexed bridge);

    /// @dev Widens MovableCollateralRouter's rebalance-domain check to also
    /// accept CCR-enrolled domains. For CCR-only domains, `setRecipient` must
    /// be called to pin a target router — `_recipient`'s fallback would
    /// otherwise revert in `_mustHaveRemoteRouter`.
    function setRecipient(
        uint32 domain,
        bytes32 recipient
    ) external override onlyOwner {
        _requireEnrolledRouter(domain);
        allowed.recipient[domain] = recipient;
        emit CCRRecipientSet(domain, recipient);
    }

    function addBridge(
        uint32 domain,
        ITokenBridge bridge
    ) external override onlyOwner {
        _requireEnrolledRouter(domain);
        _addBridge(domain, bridge);
        emit CCRBridgeAdded(domain, address(bridge));
    }

    function _requireEnrolledRouter(uint32 domain) internal view {
        require(
            routers(domain) != bytes32(0) ||
                _crossCollateralRouters[domain].length() > 0,
            "CCR: domain has no routers"
        );
    }

    /// @dev A domain also has rebalance routes if it has cross-collateral routers.
    function _MovableCollateralRouter_hasRebalanceRoutes(
        uint32 domain
    ) internal view override returns (bool) {
        return
            super._MovableCollateralRouter_hasRebalanceRoutes(domain) ||
            _crossCollateralRouters[domain].length() > 0;
    }

    // ============ Internal Helpers ============

    /// @dev Reverts unless `_router` is enrolled for `_domain` (either via the
    /// standard Router._routers map or via the CrossCollateral-specific _crossCollateralRouters set).
    function _requireAuthorizedRouter(
        uint32 _domain,
        bytes32 _router
    ) internal view {
        require(_router != bytes32(0), "CCR: router is zero address");
        require(
            _isRemoteRouter(_domain, _router) ||
                _crossCollateralRouters[_domain].contains(_router),
            "CCR: unauthorized router"
        );
    }

    // ============ Handle Override ============

    /// @dev Overrides `Router.handle` from core (`client/Router.sol`) via
    /// HypERC20Collateral -> TokenRouter -> GasRouter -> Router.
    /// Accepts messages from the mailbox (cross-chain) or directly from
    /// enrolled routers on the same chain. Removes the onlyMailbox modifier.
    // solhint-disable-next-line hyperlane/no-virtual-override
    function handle(
        uint32 _origin,
        bytes32 _sender,
        bytes calldata _message
    ) external payable override {
        if (msg.sender == address(mailbox)) {
            // Cross-chain via mailbox: origin must differ from local domain
            require(
                _origin != localDomain,
                "CCR: same-domain via mailbox not allowed"
            );
            // Cross-chain via mailbox: sender must be enrolled
            _requireAuthorizedRouter(_origin, _sender);
        } else {
            // Same-chain direct call: caller must be an enrolled router
            require(
                _crossCollateralRouters[localDomain].contains(
                    TypeCasts.addressToBytes32(msg.sender)
                ),
                "CCR: unauthorized router"
            );
        }
        _handle(_origin, _sender, _message);
    }

    // ============ Per-Router Fee Lookup ============
    // Mirrors TokenRouter._feeRecipientAndAmount but routes through
    // ICrossCollateralFee.quoteTransferRemoteTo (which includes _targetRouter)
    // instead of ITokenFee.quoteTransferRemote (destination-only).

    function _feeRecipientAndAmountForRouter(
        uint32 _destination,
        bytes32 _recipient,
        uint256 _amount,
        bytes32 _targetRouter
    ) internal view returns (address _feeRecipient, uint256 feeAmount) {
        _feeRecipient = feeRecipient();
        if (_feeRecipient == address(0)) return (_feeRecipient, 0);

        // Only difference from base: quoteTransferRemoteTo with _targetRouter
        Quote[] memory quotes = ICrossCollateralFee(_feeRecipient)
            .quoteTransferRemoteTo(
                _destination,
                _recipient,
                _amount,
                _targetRouter
            );
        if (quotes.length == 0) return (_feeRecipient, 0);

        require(
            quotes.length == 1 && quotes[0].token == token(),
            "CCR: fee must match token"
        );
        feeAmount = quotes[0].amount;
    }

    // Mirrors TokenRouter._calculateFeesAndCharge. Identical charge/hook/transfer
    // logic — only the fee lookup differs (router-aware via _feeRecipientAndAmountForRouter).
    // Duplicated here because the base hardcodes _feeRecipientAndAmount.
    function _calculateFeesAndChargeForRouter(
        uint32 _destination,
        bytes32 _recipient,
        uint256 _amount,
        uint256 _msgValue,
        bytes32 _targetRouter
    ) internal returns (uint256 externalFee, uint256 remainingNativeValue) {
        // Only difference from base: router-aware fee lookup
        (
            address _feeRecipient,
            uint256 feeAmount
        ) = _feeRecipientAndAmountForRouter(
                _destination,
                _recipient,
                _amount,
                _targetRouter
            );
        // --- remainder identical to TokenRouter._calculateFeesAndCharge ---
        externalFee = _externalFeeAmount(_destination, _recipient, _amount);
        uint256 charge = _amount + feeAmount + externalFee;

        address _feeHook = feeHook();
        address _token = token();

        // Same-domain transferRemoteTo calls handle() directly and does not dispatch
        // through mailbox hooks, so do not charge hook fees in that path.
        if (_feeHook != address(0) && _destination != localDomain) {
            uint256 hookFee = _quoteGasPaymentTo(
                _destination,
                _recipient,
                _amount,
                _token,
                _targetRouter
            );
            if (hookFee > 0) {
                if (_token != address(this)) {
                    charge += hookFee;
                } else {
                    IERC20(_token).safeTransferFrom(
                        msg.sender,
                        address(this),
                        hookFee
                    );
                }
                IERC20(_token).forceApprove(_feeHook, hookFee);
            }
        }

        _transferFromSender(charge);
        if (feeAmount > 0) {
            _transferFee(_feeRecipient, feeAmount);
        }
        remainingNativeValue = _token != address(0)
            ? _msgValue
            : _msgValue - charge;
    }

    // ============ Cross-chain Transfer to Specific Router ============

    /**
     * @notice Transfers tokens to the primary enrolled router for `_destination`.
     * @dev Uses the enrolled primary remote router for `_destination` and routes through
     * router-aware fee lookup (`ICrossCollateralFee`) via `transferRemoteTo`.
     * @dev This override is required because TokenRouter's `_feeRecipientAndAmount`
     * is non-virtual and hardcodes `ITokenFee`. Delegating through
     * `transferRemoteTo` keeps both transfer paths on `ICrossCollateralFee`.
     */
    function transferRemote(
        uint32 _destination,
        bytes32 _recipient,
        uint256 _amount
    ) public payable override returns (bytes32 messageId) {
        bytes32 targetRouter = _mustHaveRemoteRouter(_destination);
        return
            transferRemoteTo(_destination, _recipient, _amount, targetRouter);
    }

    /**
     * @notice Transfer tokens cross-chain to a specific target router.
     * @dev Follows TokenRouter.transferRemote() flow: fees → message → emit → dispatch.
     * Bypasses _Router_dispatch (which hardcodes the enrolled router) to dispatch
     * directly to the target router.
     * @param _destination Destination domain.
     * @param _recipient Final token recipient on destination.
     * @param _amount Amount in local token decimals.
     * @param _targetRouter The enrolled router to receive the message on destination.
     * @return messageId The dispatched message ID.
     */
    function transferRemoteTo(
        uint32 _destination,
        bytes32 _recipient,
        uint256 _amount,
        bytes32 _targetRouter
    ) public payable returns (bytes32 messageId) {
        _requireAuthorizedRouter(_destination, _targetRouter);
        if (_destination == localDomain) {
            // Local transfers call handle() directly without mailbox dispatch,
            // so any msg.value would be stuck in this contract permanently.
            require(msg.value == 0, "CCR: local transfer no msg.value");
        }

        (, uint256 remainingValue) = _calculateFeesAndChargeForRouter(
            _destination,
            _recipient,
            _amount,
            msg.value,
            _targetRouter
        );

        uint256 scaled = _outboundAmount(_amount);
        bytes memory tokenMsg = TokenMessage.format(_recipient, scaled);

        if (_destination == localDomain) {
            // Same-domain: call target router's handle directly
            address target = _targetRouter.bytes32ToAddress();
            require(target.code.length > 0, "CCR: target router not contract");
            CrossCollateralRouter(target).handle(
                localDomain,
                TypeCasts.addressToBytes32(address(this)),
                tokenMsg
            );
        } else {
            emit SentTransferRemote(_destination, _recipient, scaled);
            messageId = mailbox.dispatch{value: remainingValue}(
                _destination,
                _targetRouter,
                tokenMsg,
                _generateHookMetadata(_destination, feeToken()),
                IPostDispatchHook(address(hook))
            );
        }
    }

    // ============ Quoting ============

    // Mirrors TokenRouter.quoteTransferRemote. Same 3-element quote structure.
    // Differences: (1) router-aware fee lookup, (2) same-domain returns 0 gas
    // since handle() is called directly without mailbox dispatch.

    function quoteTransferRemote(
        uint32 _destination,
        bytes32 _recipient,
        uint256 _amount
    ) public view override returns (Quote[] memory quotes) {
        bytes32 targetRouter = _mustHaveRemoteRouter(_destination);
        return
            quoteTransferRemoteTo(
                _destination,
                _recipient,
                _amount,
                targetRouter
            );
    }

    /// @inheritdoc ICrossCollateralFee
    function quoteTransferRemoteTo(
        uint32 _destination,
        bytes32 _recipient,
        uint256 _amount,
        bytes32 _targetRouter
    ) public view override returns (Quote[] memory quotes) {
        _requireAuthorizedRouter(_destination, _targetRouter);
        if (_destination == localDomain) {
            require(
                _targetRouter.bytes32ToAddress().code.length > 0,
                "CCR: target router not contract"
            );
        }

        quotes = new Quote[](3);

        // Same-domain: handle() called directly, no interchain gas
        uint256 gasQuote = 0;
        address _feeToken = feeToken();
        if (_destination != localDomain) {
            gasQuote = _quoteGasPaymentTo(
                _destination,
                _recipient,
                _amount,
                _feeToken,
                _targetRouter
            );
        }
        quotes[0] = Quote({token: _feeToken, amount: gasQuote});

        // Only difference from base: router-aware fee lookup
        (, uint256 feeAmount) = _feeRecipientAndAmountForRouter(
            _destination,
            _recipient,
            _amount,
            _targetRouter
        );
        quotes[1] = Quote({token: token(), amount: _amount + feeAmount});

        quotes[2] = Quote({
            token: token(),
            amount: _externalFeeAmount(_destination, _recipient, _amount)
        });
    }

    /// @dev Target-router-aware gas quote helper. Avoids Router._mustHaveRemoteRouter().
    /// Caller must validate `_targetRouter` is authorized for `_destination`.
    function _quoteGasPaymentTo(
        uint32 _destination,
        bytes32 _recipient,
        uint256 _amount,
        address _feeToken,
        bytes32 _targetRouter
    ) internal view returns (uint256) {
        return
            mailbox.quoteDispatch(
                _destination,
                _targetRouter,
                TokenMessage.format(_recipient, _outboundAmount(_amount)),
                _generateHookMetadata(_destination, _feeToken),
                IPostDispatchHook(address(hook))
            );
    }
}

contracts/token/CrossCollateralRoutingFe.content:
// SPDX-License-Identifier: MIT OR Apache-2.0
pragma solidity >=0.8.0;

import {ICrossCollateralFee} from "./interfaces/ICrossCollateralFee.sol";
import {ITokenFee, Quote} from "../interfaces/ITokenBridge.sol";
import {PackageVersioned} from "../PackageVersioned.sol";
import {FeeType} from "./fees/BaseFee.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title CrossCollateralRoutingFee
 * @notice Routes fee lookups by destination + target router. Delegates to
 * existing ITokenFee (3-param) fee contracts (LinearFee, ProgressiveFee, etc.).
 * @dev This contract assumes standard ERC20 behavior for fee balances and
 * transfers. Rebasing, fee-on-transfer, and ERC777 tokens are not supported
 * for deterministic fee accounting.
 */
// solhint-disable-next-line hyperlane/enumerable-domain-mapping
contract CrossCollateralRoutingFee is
    ICrossCollateralFee,
    ITokenFee,
    Ownable,
    PackageVersioned
{
    using SafeERC20 for IERC20;

    /// @notice Sentinel key for destination-level default fee contracts.
    bytes32 public constant DEFAULT_ROUTER =
        keccak256("RoutingFee.DEFAULT_ROUTER");

    /// @notice Per destination + per target router → fee contract.
    /// Destination defaults use DEFAULT_ROUTER as targetRouter.
    mapping(uint32 dest => mapping(bytes32 targetRouter => address feeContract))
        public feeContracts;

    event FeeContractSet(
        uint32 destination,
        bytes32 targetRouter,
        address feeContract
    );

    constructor(address _owner) Ownable() {
        _transferOwnership(_owner);
    }

    function setCrossCollateralRouterFeeContracts(
        uint32[] calldata destinations,
        bytes32[] calldata targetRouters,
        address[] calldata _feeContracts
    ) external onlyOwner {
        require(
            destinations.length == targetRouters.length &&
                destinations.length == _feeContracts.length,
            "CCRF: length mismatch"
        );

        for (uint256 i = 0; i < destinations.length; i++) {
            feeContracts[destinations[i]][targetRouters[i]] = _feeContracts[i];
            emit FeeContractSet(
                destinations[i],
                targetRouters[i],
                _feeContracts[i]
            );
        }
    }

    function claim(address beneficiary, address token) external onlyOwner {
        uint256 balance = IERC20(token).balanceOf(address(this));
        IERC20(token).safeTransfer(beneficiary, balance);
    }

    function feeType() external pure returns (FeeType) {
        return FeeType.CROSS_COLLATERAL_ROUTING;
    }

    /**
     * @inheritdoc ITokenFee
     * @dev Quotes destination-level fee using DEFAULT_ROUTER sentinel.
     */
    function quoteTransferRemote(
        uint32 _destination,
        bytes32 _recipient,
        uint256 _amount
    ) external view override returns (Quote[] memory) {
        return
            _quoteTransferRemote(
                _destination,
                _recipient,
                _amount,
                DEFAULT_ROUTER
            );
    }

    /**
     * @inheritdoc ICrossCollateralFee
     * @dev Routes: specific router → destination default (DEFAULT_ROUTER).
     */
    function quoteTransferRemoteTo(
        uint32 _destination,
        bytes32 _recipient,
        uint256 _amount,
        bytes32 _targetRouter
    ) external view override returns (Quote[] memory) {
        return
            _quoteTransferRemote(
                _destination,
                _recipient,
                _amount,
                _targetRouter
            );
    }

    function _quoteTransferRemote(
        uint32 _destination,
        bytes32 _recipient,
        uint256 _amount,
        bytes32 _targetRouter
    ) internal view returns (Quote[] memory) {
        // 1. Check per-router fee
        address routerFee = feeContracts[_destination][_targetRouter];
        if (routerFee != address(0)) {
            return
                ITokenFee(routerFee).quoteTransferRemote(
                    _destination,
                    _recipient,
                    _amount
                );
        }
        // 2. Fallback to destination default
        address destFee = feeContracts[_destination][DEFAULT_ROUTER];
        if (destFee != address(0)) {
            return
                ITokenFee(destFee).quoteTransferRemote(
                    _destination,
                    _recipient,
                    _amount
                );
        }
        // 3. No fee configured for router or destination default
        revert("CCRF: no fee contract");
    }
}

contracts/token/extensions/HypERC4626.so.content:
// SPDX-License-Identifier: MIT OR Apache-2.0
pragma solidity >=0.8.0;

/*@@@@@@@       @@@@@@@@@
 @@@@@@@@@       @@@@@@@@@
  @@@@@@@@@       @@@@@@@@@
   @@@@@@@@@       @@@@@@@@@
    @@@@@@@@@@@@@@@@@@@@@@@@@
     @@@@@  HYPERLANE  @@@@@@@
    @@@@@@@@@@@@@@@@@@@@@@@@@
   @@@@@@@@@       @@@@@@@@@
  @@@@@@@@@       @@@@@@@@@
 @@@@@@@@@       @@@@@@@@@
@@@@@@@@@       @@@@@@@@*/

// ============ Internal Imports ============
import {HypERC20} from "../HypERC20.sol";
import {Message} from "../../libs/Message.sol";
import {TokenMessage} from "../libs/TokenMessage.sol";
import {TokenRouter} from "../libs/TokenRouter.sol";
import {Router} from "../../client/Router.sol";

// ============ External Imports ============
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";

/**
 * @title Hyperlane ERC20 Rebasing Token
 * @author Abacus Works
 * @notice This contract implements a rebasing token that reflects yields from the origin chain
 * @dev Messages contain amounts as shares of ERC4626 and exchange rate of assets per share.
 * @dev internal ERC20 balances storage mapping is in share units
 * @dev internal ERC20 allowances storage mapping is in asset units
 * @dev public ERC20 interface is in asset units
 */
contract HypERC4626 is HypERC20 {
    using Math for uint256;
    using Message for bytes;
    using TokenMessage for bytes;

    event ExchangeRateUpdated(uint256 newExchangeRate, uint32 rateUpdateNonce);

    uint256 public constant PRECISION = 1e10;
    uint32 public immutable collateralDomain;
    uint256 public exchangeRate; // 1e10
    uint32 public previousNonce;

    constructor(
        uint8 _decimals,
        uint256 _scaleNumerator,
        uint256 _scaleDenominator,
        address _mailbox,
        uint32 _collateralDomain
    ) HypERC20(_decimals, _scaleNumerator, _scaleDenominator, _mailbox) {
        collateralDomain = _collateralDomain;
        exchangeRate = 1e10;
        _disableInitializers();
    }

    // ============ Public Functions ============

    /// Override totalSupply to return the total assets instead of shares. This reflects the actual circulating supply in terms of assets, accounting for rebasing
    /// @inheritdoc ERC20Upgradeable
    function totalSupply() public view override returns (uint256) {
        return sharesToAssets(totalShares());
    }

    /// This returns the balance of the account in terms of assets, accounting for rebasing
    /// @inheritdoc ERC20Upgradeable
    function balanceOf(address account) public view override returns (uint256) {
        return sharesToAssets(shareBalanceOf(account));
    }

    /// This function provides the total supply in terms of shares
    function totalShares() public view returns (uint256) {
        return super.totalSupply();
    }

    ///  This returns the balance of the account in terms of shares
    function shareBalanceOf(address account) public view returns (uint256) {
        return super.balanceOf(account);
    }

    function assetsToShares(uint256 _amount) public view returns (uint256) {
        return _amount.mulDiv(PRECISION, exchangeRate);
    }

    function sharesToAssets(uint256 _shares) public view returns (uint256) {
        return _shares.mulDiv(exchangeRate, PRECISION);
    }

    // @inheritdoc HypERC20
    // @dev Amount specified by the user is in assets, but the internal accounting is in shares
    function _transferFromSender(uint256 _amount) internal override {
        HypERC20._transferFromSender(assetsToShares(_amount));
    }

    // @inheritdoc TokenRouter
    // @dev Amount specified by user is in assets, but the message accounting is in shares
    function _outboundAmount(
        uint256 _localAmount
    ) internal view override returns (uint256) {
        return TokenRouter._outboundAmount(assetsToShares(_localAmount));
    }

    // @inheritdoc ERC20Upgradeable
    // @dev Amount specified by user is in assets, but the internal accounting is in shares
    function _transfer(
        address _from,
        address _to,
        uint256 _amount
    ) internal override {
        super._transfer(_from, _to, assetsToShares(_amount));
    }

    // `_inboundAmount` implementation reused from `TokenRouter` unchanged because message
    // accounting is in shares

    // ========== TokenRouter extensions ============
    /// @inheritdoc TokenRouter
    function _handle(
        uint32 _origin,
        bytes32 _sender,
        bytes calldata _message
    ) internal override {
        if (_origin == collateralDomain) {
            (uint256 newExchangeRate, uint32 rateUpdateNonce) = abi.decode(
                _message.metadata(),
                (uint256, uint32)
            );
            // only update if the nonce is greater than the previous nonce
            if (rateUpdateNonce > previousNonce) {
                exchangeRate = newExchangeRate;
                previousNonce = rateUpdateNonce;
                emit ExchangeRateUpdated(exchangeRate, rateUpdateNonce);
            }
        }
        super._handle(_origin, _sender, _message);
    }
}

